import type { Metadata } from "next";
import Link from "next/link";

import SearchForm from "@/components/search/SearchForm";
import SearchResultsExperience from "@/components/search/SearchResultsExperience";
import { getGeneralSearchResults } from "@/lib/search/searchResults";
import { normalizeSearchQuery } from "@/lib/searchIntent";

export const runtime = "edge";

type SearchPageProps = {
  searchParams?: {
    query?: string;
    city?: string;
    when?: string;
    category?: string;
    free?: string;
    rating?: string;
    sort?: string;
  };
};

export function generateMetadata({ searchParams }: SearchPageProps): Metadata {
  const query = normalizeSearchQuery(searchParams?.query);
  return query
    ? { title: `Zoeken naar ${query} | Uitjes`, description: `Bekijk zoekresultaten voor ${query}.`, alternates: { canonical: "/zoeken" } }
    : { title: "Zoeken | Uitjes", description: "Vind inspiratie, activiteiten en lokale tips die bij je passen.", alternates: { canonical: "/zoeken" } };
}

const popularSearches = [
  { label: "Buiten", query: "buiten" },
  { label: "Vandaag", query: "vandaag" },
  { label: "Dit weekend", query: "weekend" },
  { label: "Gratis", query: "gratis" },
  { label: "Met kinderen", query: "kinderen" },
];

const discoveryRoutes = [
  { eyebrow: "Moment", title: "Vandaag", description: "Spontane plannen zonder veel voorbereiding.", href: "/zoeken?query=vandaag&when=today" },
  { eyebrow: "Samen", title: "Met kinderen", description: "Laagdrempelige ideeën voor het hele gezin.", href: "/zoeken?query=kinderen&category=met-kinderen" },
  { eyebrow: "Buiten", title: "In de buurt", description: "Ontdek lokale plekken en activiteiten.", href: "/ontdek" },
];

export default async function SearchPage({ searchParams }: SearchPageProps) {
  const query = normalizeSearchQuery(searchParams?.query);
  const searchState = query
    ? await getGeneralSearchResults(query)
    : { status: "success" as const, results: [] };

  return (
    <main className="min-h-screen bg-[#f6f5f0] text-[#22312a]">
      <section className="search-hero border-b border-[#dce4dc]" aria-labelledby="search-page-title">
        <div className="relative z-10 mx-auto max-w-[1280px] px-4 pb-12 pt-28 sm:px-6 sm:pb-14 sm:pt-32 lg:px-8 lg:pb-16">
          <div className="max-w-4xl">
            <div className="flex flex-wrap items-center gap-x-3 gap-y-2 text-[0.67rem] font-bold uppercase tracking-[0.18em] text-[#5e7c68]">
              <span className="inline-flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[#1d5a46]" />DOEN zoeken</span>
              <span className="h-px w-8 bg-[#abc0ad]" aria-hidden="true" />
              <span className="font-medium tracking-[0.12em] text-[#78917e]">Vind je volgende plan</span>
            </div>
            <h1 id="search-page-title" className="mt-5 font-heading text-[clamp(3.5rem,8vw,6.8rem)] leading-[0.82] tracking-[-0.075em] text-[#1f3027]">Zoeken</h1>
            <p className="mt-5 max-w-2xl text-[0.98rem] leading-7 text-[#586b60] sm:text-[1.08rem]">Vind inspiratie, activiteiten en lokale tips die bij je passen.</p>

            <div className="mt-7 max-w-3xl">
              <SearchForm
                initialQuery={query}
                className="!rounded-[1.4rem] !border-[#cbd9cd] !bg-white/90 !p-2 !shadow-[0_18px_42px_rgba(29,68,48,0.1)] sm:!rounded-[1.4rem]"
              />
            </div>

            <div className="mt-4 flex flex-wrap items-center gap-2.5" aria-label="Populaire zoektermen">
              <span className="mr-1 text-xs font-medium text-[#718278]">Populair</span>
              {popularSearches.map((item) => (
                <Link key={item.query} href={`/zoeken?query=${item.query}`} className="inline-flex min-h-9 items-center rounded-full border border-[#cddacd] bg-white/50 px-3.5 text-xs font-semibold text-[#41614d] outline-none transition hover:border-[#1d5a46] hover:bg-white focus-visible:ring-2 focus-visible:ring-[#005fcc]">
                  {item.label}
                </Link>
              ))}
            </div>
          </div>
        </div>
      </section>

      {query ? (
        <SearchResultsExperience query={query} results={searchState.status === "success" ? searchState.results : []} error={searchState.status === "error"} />
      ) : (
        <section className="mx-auto max-w-[1280px] px-4 pb-20 pt-10 sm:px-6 sm:pt-14 lg:px-8" aria-labelledby="search-start-heading">
          <div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <span className="search-section-label">Begin hier</span>
              <h2 id="search-start-heading" className="mt-2 font-heading text-[clamp(2rem,4vw,3rem)] leading-none tracking-[-0.055em] text-[#22312a]">Waar heb je zin in?</h2>
            </div>
            <p className="max-w-sm text-sm leading-6 text-[#718078] sm:text-right">Kies een richting en verfijn daarna rustig verder.</p>
          </div>
          <div className="mt-7 grid gap-4 md:grid-cols-3">
            {discoveryRoutes.map((route) => (
              <Link key={route.href} href={route.href} className="group rounded-[1.45rem] border border-[#dce1dc] bg-white p-5 outline-none transition duration-300 hover:-translate-y-1 hover:border-[#aec5b2] hover:shadow-[0_18px_36px_rgba(33,54,43,0.08)] focus-visible:ring-2 focus-visible:ring-[#005fcc] sm:p-6">
                <span className="text-[0.66rem] font-bold uppercase tracking-[0.16em] text-[#6f8d77]">{route.eyebrow}</span>
                <span className="mt-8 flex items-end justify-between gap-4">
                  <span>
                    <span className="block font-heading text-3xl leading-none tracking-[-0.055em] text-[#243a2d]">{route.title}</span>
                    <span className="mt-3 block text-sm leading-6 text-[#718078]">{route.description}</span>
                  </span>
                  <span className="mb-1 inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-[#ccd9ce] text-[#376148] transition group-hover:translate-x-1 group-hover:border-[#1d5a46]" aria-hidden="true">→</span>
                </span>
              </Link>
            ))}
          </div>
        </section>
      )}
    </main>
  );
}
