"use client";

import { AppButton } from "@/components/ui/app";
import SearchForm from "@/components/search/SearchForm";
import { normalizeSearchQuery } from "@/lib/searchIntent";

export default function SearchError({ reset }: { error: Error & { digest?: string }; reset: () => void }) {
  const query = normalizeSearchQuery(new URLSearchParams(window.location.search).get("query"));

  return (
    <main className="min-h-screen bg-[#f6f5f0] text-[#22312a]">
      <section className="search-hero border-b border-[#dce4dc]">
        <div className="mx-auto max-w-[1280px] px-4 pb-12 pt-28 sm:px-6 sm:pb-14 sm:pt-32 lg:px-8">
          <span className="text-[0.67rem] font-bold uppercase tracking-[0.18em] text-[#5e7c68]">DOEN zoeken</span>
          <h1 className="mt-5 font-heading text-[clamp(3.5rem,8vw,6.8rem)] leading-[0.82] tracking-[-0.075em] text-[#1f3027]">Zoeken</h1>
          <div className="mt-7 max-w-3xl"><SearchForm initialQuery={query} /></div>
        </div>
      </section>
      <section className="mx-auto max-w-[1280px] px-4 pb-20 pt-8 sm:px-6 lg:px-8" role="alert" aria-labelledby="search-error-heading">
        <div className="search-empty-state max-w-2xl">
          <div>
            <span className="search-section-label">Zoekresultaten</span>
            <h2 id="search-error-heading" className="mt-3 font-heading text-[clamp(2rem,4vw,3.3rem)] leading-[0.98] tracking-[-0.055em] text-[#22312a]">We kunnen de resultaten niet laden.</h2>
            <p className="mt-3 max-w-xl text-sm leading-6 text-[#68746d] sm:text-base">Er ging iets mis tijdens het zoeken. Probeer het nog een keer.</p>
            <div className="mt-6"><AppButton type="button" variant="dark" onClick={reset}>Opnieuw proberen</AppButton></div>
          </div>
        </div>
      </section>
    </main>
  );
}
